esso'])?>"></label><label>Documento de referência <input name="documento_referencia" maxlength="255" value="<?=e($event['documento_referencia'])?>"></label><label class="checkbox-label"><input type="checkbox" name="atividade_fornecida_sed" value="1" <?=$event['atividade_fornecida_sed']?'checked':''?>> Atividade fornecida pela SED</label></div><div class="actions"><button class="primary">Salvar alterações</button></div></form><?php if($event['status']==='ATIVO'):?><form method="post" action="/apc/admin/eventos/<?=e($event['id'])?>/cancelar"><input type="hidden" name="_csrf" value="<?=e($csrf)?>"><button class="danger" data-confirm="Cancelar este evento sem apagar o histórico?">Cancelar evento</button></form><?php else:?><form method="post" action="/apc/admin/eventos/<?=e($event['id'])?>/reativar"><input type="hidden" name="_csrf" value="<?=e($csrf)?>"><button class="primary" data-confirm="Reativar este evento e disponibilizá-lo novamente aos professores?">Reativar evento</button></form><?php endif;?></details><?php endforeach;?></div><?php endif;?>
